settings.custom_liquid:
{%- comment -%}
  Escasez CONCRETA con el inventario real de la variante elegida.
  Sustituye al "🔥 Últimos días de oferta" de la v1, que era escasez genérica y
  violaba nuestra propia regla ("escasez concreta o nada").

  Solo se pinta si Shopify trackea inventario y quedan pocas unidades de ESA
  talla y color. El JSON de abajo lo lee el script para actualizar el número al
  cambiar de variante, sin recargar la página.
{%- endcomment -%}
{%- liquid
  assign umbral = product.metafields.custom.stock_umbral | default: 25 | plus: 0
  comment
    OJO: `product.tracks_inventory` NO existe en Liquid — es un campo de la Admin
    API y evaluarlo devuelve nil, así que el bloque entero desaparecía en silencio.
    En Liquid el inventario se pregunta POR VARIANTE con inventory_management.
  endcomment
  assign trackea = false
  for var in product.variants
    if var.inventory_management != blank
      assign trackea = true
      break
    endif
  endfor
-%}
{%- if trackea -%}
  {%- capture inv_json -%}
    {
    {%- for var in product.variants -%}
      "{{ var.id }}": {{ var.inventory_quantity | default: 0 }}{%- unless forloop.last -%},{%- endunless -%}
    {%- endfor -%}
    }
  {%- endcapture -%}
  <script type="application/json" id="v2-inv">{{ inv_json }}</script>
  <div class="v2-stock" id="v2-stock" data-umbral="{{ umbral }}" hidden>
    <span class="v2-stock-dot"></span>
    <span class="v2-stock-tx"></span>
  </div>
  <style>
    .v2-stock{display:flex;align-items:center;gap:8px;margin:10px 0 4px;
              font-size:1.05rem;font-weight:600;color:#B3261E}
    .v2-stock-dot{width:9px;height:9px;border-radius:50%;background:#B3261E;
                  animation:v2pulse 1.6s ease-in-out infinite;flex:0 0 auto}
    @keyframes v2pulse{0%,100%{opacity:1}50%{opacity:.35}}
    @media (prefers-reduced-motion: reduce){.v2-stock-dot{animation:none}}
  </style>
  <script>
  (function(){
    var caja = document.getElementById('v2-stock');
    var datos = document.getElementById('v2-inv');
    if (!caja || !datos) return;
    var inv;
    try { inv = JSON.parse(datos.textContent); } catch (e) { return; }
    var umbral = parseInt(caja.dataset.umbral, 10) || 25;
    var tx = caja.querySelector('.v2-stock-tx');

    function idVariante() {
      var u = new URL(window.location.href);
      var v = u.searchParams.get('variant');
      if (v) return v;
      var campo = document.querySelector('form[action*="/cart/add"] [name="id"]');
      return campo ? campo.value : null;
    }
    function pintar() {
      var id = idVariante();
      var n = id ? inv[id] : undefined;
      if (typeof n !== 'number' || n <= 0 || n > umbral) { caja.hidden = true; return; }
      tx.textContent = n === 1 ? 'Queda 1 unidad en esta talla' : 'Quedan ' + n + ' unidades en esta talla';
      caja.hidden = false;
    }
    // Este bloque se renderiza ANTES que buy_buttons, así que al ejecutarse el
    // formulario todavía no existe. Observar el form directamente registraba el
    // observer sobre null y el número no se pintaba nunca; observar el body con
    // {subtree, attributes} dispara miles de veces y cuelga la página. La vía
    // sana: esperar al form con reintentos acotados y observar SOLO ese form.
    var intentos = 0;
    function engancharse() {
      var form = document.querySelector('form[action*="/cart/add"]');
      if (!form) {
        if (++intentos > 20) return;          // ~6 s y se rinde, sin bucles vivos
        return setTimeout(engancharse, 300);
      }
      pintar();
      new MutationObserver(pintar).observe(form, {
        subtree: true, attributes: true, attributeFilter: ['value']
      });
      form.addEventListener('change', pintar);
    }
    engancharse();
    window.addEventListener('popstate', pintar);
  })();
  </script>
{%- endif -%}
